  imports: [CommonModule, AppTestingModule], // Import the AppModule
  providers: [],
  bootstrap: [FeatureAComponent]
})
export class FeatureAModule {}
```
Here, we're importing the `AppTestingModule` (which imports the `AppModule`) in the `FeatureAModule`.

