              4 * pow(1 + (z * alpha + h[i]) / (alpha * h[i]), 2) +
              1 - 4 * pow(1 + (z * alpha + h[i]) / (alpha * h[i]), 4) * log(1 + (z * alpha + h[i]) / (alpha * h[i])));
  }

  for (int n = 0; n < num_steps; n++) {
    for (int i = 0; i <= N; i++) {
