      double a = 1 / (alpha * h[i]);
      double b = M[i] * alpha / (alpha * h[i]);
      double c = 1 + (h[i + 1] - h[i - 1]) / (2 * dz) * M[i] * alpha / (alpha * h[i]);
      double d = 1 / (alpha * h[i]) + 1 / (alpha * h[i + 1]) + 1 / (alpha * h[i - 1]);
      double r = 1 / (alpha * h[i]) * (c - b) / d;

      // решаем систему линейных алгебраических уравнений для h и p
      double h_new = h[i] + dt * (a * (p[i + 1] - p[i - 1]) - b * r * (h[i + 1] - h[i - 1]));
