```
class Password {
  constructor() {}

  getRandomChars(length) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%&*';
    return Array(length).fill('').map(() => chars.charAt(Math.floor(Math.random() * chars.length))).join('');
  }

  generatePassword(length = 12) {
    const password = this.getRandomChars(length / 2);
    const specialChars = this.getRandomChars(length / 4);
    const numbers = this.getRandomChars(length / 4);
    return `${password}${specialChars}${numbers}`;
  }

  checkPasswordStrength(password) {
    const hasUpper = /[A-Z]/.test(password);
    const hasLower = /[a-z]/.test(password);
    const hasNumber = /[0-9]/.test(password);
    const hasSpecial = /[!@#$%&*]/.test(password);

    if (hasUpper && hasLower && hasNumber && hasSpecial && password.length >= 12) {
      return true;
    } else {
      return false;
    }
  }
}
```
