// функция для вычисления интеграла методом прямоугольников
double integral_rectangles(double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += h * (a + i * h);
    }
    return result;
}

// функция для вычисления интеграла методом трапеций
double integral_trapeze(double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += h * (a + i * h + h / 2);
    }
    return result;
}

// функция для вычисления интеграла методом Симпсона
double integral_simpson(double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1) {
            result += h * (a + i * h);
        } else if (i % 2 == 0) {
            result += 2 * h * (a + i * h);
        } else {
            result += 4 * h * (a + i * h);
        }
    }
    return result;
}

