    int *n = (int*)lpParam;
    double a = 0;
    double b = 1;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(-1, 1);
    double result = 0;
    for (int i = 0; i < (*n); i++) {
        result += integral_rectangles(a, b, i);
        Sleep(dis(gen) * 100);
    }
    return 0;
}

