class EloRating:
    def __init__(self, initial_rating=1200):
        self.rating = initial_rating

    def update(self, against_rating, result):
        K = 16
        expected = 1 / (1 + 10 ** ((against_rating - self.rating) / 400))
        self.rating += K * (result - expected)

    def __str__(self):
        return f"{self.rating:.2f}"

class Tournament:
    def __init__(self, players, rounds):
        self.players = [EloRating() for _ in range(players)]
        self.rounds = rounds

    def play_round(self):
        for i, p1 in enumerate(self.players):
            against = [p for p in self.players if p != p1][i % (len(self.players) - 1)]
            result = int(input(f"Player {i+1} ({p1}) vs Player {i+2} ({against}) (1 for win, 0 for loss, 0.5 for draw): "))
            p1.update(against.rating, result)
            against.update(p1.rating, 1 - result)

    def play(self):
        for _ in range(self.rounds):
            print(f"Round {_+1}:")
            [print(f"{i+1}. {player}") for i, player in enumerate(self.players)]
            self.play_round()
            print("\n")

    def get_results(self):
        return ', '.join([str(player) for player in self.players])

